  "implementation": "import heapq

def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_dict = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}  # parent -> list of child ids
    child_count = {n['id']: 0 for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
            child_count[p] += 1
    # initial heap: (-depth, node_id) for descending depth, then ascending id
    heap = []
    enqueued = set()
    for n in nodes:
        priority = (-n['depth'], n['id'])
        heapq.heappush(heap, priority)
        enqueued.add(n['id'])
    processed = set()
    removed = set()
    visit_order = []
    while heap:
        neg_depth, node_id = heapq.heappop(heap)
        if node_id in processed or node_id in removed:
            continue
        processed.add(node_id)
        visit_order.append(node_id)
        if node_id in removed:
            continue
        # check if leaf and removable and utility <= threshold
        if child_count[node_id] == 0 and node_dict[node_id]['removable'] and node_dict[node_id]['utility'] <= threshold:
            # remove node
            removed.add(node_id)
            parent_id = node_dict[node_id]['parent']
            if parent_id is not None and parent_id not in removed:
                child_count[parent_id] -= 1
                if parent_id not in processed and parent_id not in enqueued:
                    parent_priority = (-node_dict[parent_id]['depth'], parent_id)
                    heapq.heappush(heap, parent_priority)
                    enqueued.add(parent_id)
    retained = [n['id'] for n in nodes if n['id'] not in removed]
    return {
        'retained_node_ids': retained,
        'visit_order': visit_order
    }
